/**
 * Generates the adapter and module registries from configuration:
 *   ai-adapters.config.json -> packages/ai-gateway/src/adapters.generated.ts
 *   modules.config.json     -> apps/api/src/modules.generated.ts
 * Adding a provider or module = new package + config entry; no hand edits to gateway core or apps.
 *   node tooling/gen-registries.ts [--check]   (--check fails if generated files are stale; used in CI)
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { join, resolve } from 'node:path'

const root = resolve(import.meta.dirname, '..')
const check = process.argv.includes('--check')
let stale = false

function emit(path: string, content: string) {
  const full = join(root, path)
  const prev = existsSync(full) ? readFileSync(full, 'utf8') : ''
  if (prev === content) return
  if (check) {
    console.error(`stale generated file: ${path} (run node tooling/gen-registries.ts)`)
    stale = true
    return
  }
  writeFileSync(full, content)
  console.log(`wrote ${path}`)
}

const ident = (s: string) => s.replace(/[^a-zA-Z0-9]/g, '_')
const HEADER = '// GENERATED by tooling/gen-registries.ts — do not edit by hand.\n'

const adapters = JSON.parse(readFileSync(join(root, 'ai-adapters.config.json'), 'utf8')) as { enabled: string[] }
emit(
  'packages/ai-gateway/src/adapters.generated.ts',
  HEADER +
    "import type { ProviderAdapter } from '@platform/ai-adapter-kit'\n" +
    adapters.enabled.map((a) => `import { adapter as ${ident(a)} } from '@platform/ai-adapter-${a}'\n`).join('') +
    '\nexport const ADAPTERS: Record<string, ProviderAdapter> = {\n' +
    adapters.enabled.map((a) => `  [${ident(a)}.descriptor.type]: ${ident(a)},\n`).join('') +
    '}\n',
)

const modules = JSON.parse(readFileSync(join(root, 'modules.config.json'), 'utf8')) as { enabled: { id: string; package: string }[] }
emit(
  'apps/api/src/modules.generated.ts',
  HEADER +
    "import type { ModuleManifest } from '@platform/contracts'\n" +
    modules.enabled.map((m) => `import { manifest as ${ident(m.id)} } from '${m.package}'\n`).join('') +
    '\nexport const MODULES: ModuleManifest[] = [' + modules.enabled.map((m) => ident(m.id)).join(', ') + ']\n',
)

if (stale) process.exit(1)
